START TRANSACTION;

UPDATE quiz_sessions qs
JOIN public_wordbooks pw ON pw.id = qs.target_id
SET qs.status = 'CANCELLED',
    qs.finished_at = CURRENT_TIMESTAMP
WHERE qs.target_type = 'PUBLIC_WORDBOOK'
  AND qs.status = 'ACTIVE'
  AND pw.tag IN (CONVERT(UNHEX('6a756e696f72') USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(UNHEX('68696768') USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(UNHEX('63657434') USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(UNHEX('63657436') USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(UNHEX('6b79') USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(UNHEX('746f65666c') USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(UNHEX('736174') USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(UNHEX('69656c7473') USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(UNHEX('677265') USING utf8mb4) COLLATE utf8mb4_unicode_ci);


DELETE FROM public_wordbooks WHERE tag IN (CONVERT(UNHEX('69656c7473') USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(UNHEX('677265') USING utf8mb4) COLLATE utf8mb4_unicode_ci);

